def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    border = next((v for row in g for v in row if v != 2), None)
    if border is None:
        return g
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            outside = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y == 0 or x == 0 or y == h-1 or x == w-1:
                    outside = True
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == 2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if not outside:
                for y, x in comp:
                    g[y][x] = 4
    return g
